#include <bits/stdc++.h>
using namespace std;

int main() {
    unordered_map<string, int> cnt;
    string w;
    while (cin >> w) cnt[w]++;
    vector<pair<string, int>> v(cnt.begin(), cnt.end());
    sort(v.begin(), v.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    for (auto& [s, c] : v) cout << s << ' ' << c << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    unordered_map<int, int> first;
    vector<int> a = {7, 3, 7, 1, 3, 3, 9};
    for (int i = 0; i < (int)a.size(); i++)
        if (!first.count(a[i])) first[a[i]] = i;
    cout << first.size() << '\n';

    cout << (first.count(5) ? "yes" : "no") << ' ' << first.size() << '\n';
    if (first[5] == 0) cout << "first[5] is 0, ";
    cout << "size now " << first.size() << '\n';
    return 0;
}

